-- Phase 4C: provider-neutral accounting facts, reconciliation, and operational projections.
alter table app_private.outbox_events drop constraint outbox_events_producer_module_check;
alter table app_private.outbox_events add constraint outbox_events_producer_module_check check (producer_module in ('identity-access','clients','service-addresses','service-configuration','geography','workforce','vehicles','daily-roster','routes','route-operations','vehicle-tracking','operational-issues','needs-attention','communications','integrations','configuration','reporting','audit','system-health','platform-runtime','operational-intelligence','website-intake','client-migration','accounting'));
insert into app_private.permissions(permission_key,description) values
 ('accounting.read','Read operational account status'),('accounting.sensitive.read','Read balances, invoices, and payments'),('accounting.sync','Start and inspect accounting syncs'),('accounting.reconcile','Resolve accounting customer mappings'),('accounting.exception.manage','Manage operational account exceptions'),('accounting.integration.manage','Manage accounting provider lifecycle') on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key)
 select r.role_id,p.permission_key from app_private.roles r cross join app_private.permissions p where r.role_key='director_admin' and p.permission_key like 'accounting.%' on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key)
 select r.role_id,p.permission_key from app_private.roles r join app_private.permissions p on p.permission_key in('accounting.read','accounting.sensitive.read','accounting.sync','accounting.reconcile','accounting.exception.manage') where r.role_key='operations_manager' on conflict do nothing;
insert into app_private.role_permissions(role_id,permission_key)
 select r.role_id,p.permission_key from app_private.roles r join app_private.permissions p on p.permission_key in('accounting.read','accounting.sensitive.read','accounting.reconcile','accounting.exception.manage') where r.role_key='office_admin' on conflict do nothing;

insert into app_private.configuration_definitions(configuration_key,description,value_type,is_required,default_value) values
 ('accounting.provider','Accounting provider adapter','string',true,'"zoho-books-fake"'),('accounting.organization-id','Non-secret provider organization identifier','string',false,'"local-synthetic"'),('accounting.sync-mode','Accounting sync mode','string',true,'"manual"'),('accounting.timeout-ms','Provider request timeout','number',true,'15000'),('accounting.page-size','Provider page size','number',true,'100'),('accounting.sync-cadence-minutes','Scheduled-sync foundation','number',true,'1440'),('accounting.lookback-days','Incremental lookback','number',true,'7'),('accounting.max-retries','Transient retry count','number',true,'2'),('accounting.max-retry-delay-ms','Retry-after cap','number',true,'5000'),('accounting.stale-after-hours','Snapshot freshness threshold','number',true,'48'),('accounting.due-soon-days','Due-soon threshold','number',true,'7'),('accounting.serious-overdue-days','Serious-overdue threshold','number',true,'60') on conflict do nothing;

create table app_private.accounting_connections(
 accounting_connection_id uuid primary key default gen_random_uuid(), provider text not null, environment_name text not null check(environment_name in('local','staging','production')), organization_reference text not null, lifecycle_status text not null check(lifecycle_status in('configured','active','degraded','disabled','authentication_required','unhealthy')), credential_reference text, last_successful_sync_at timestamptz, last_attempt_at timestamptz, health_summary text, updated_at timestamptz not null default now(), unique(provider,environment_name,organization_reference));
create table app_private.accounting_sync_runs(
 accounting_sync_run_id uuid primary key default gen_random_uuid(), accounting_connection_id uuid not null references app_private.accounting_connections, provider text not null, environment_name text not null, sync_mode text not null check(sync_mode in('initial_full','incremental','manual_refresh','scheduled')), lifecycle_status text not null check(lifecycle_status in('pending','running','succeeded','partial','failed','cancelled')), cursor_before text, cursor_after text, started_at timestamptz, completed_at timestamptz, initiated_by uuid references auth.users, initiation_kind text not null check(initiation_kind in('user','system')), correlation_id uuid not null, fetched_counts jsonb not null default '{}', processed_counts jsonb not null default '{}', reconciliation_counts jsonb not null default '{}', failure_classification text, safe_failure_message text, provider_metadata jsonb not null default '{}', created_at timestamptz not null default now());
create index accounting_sync_runs_connection_time_idx on app_private.accounting_sync_runs(accounting_connection_id,created_at desc);
create table app_private.accounting_customer_facts(
 accounting_customer_fact_id uuid primary key default gen_random_uuid(), accounting_sync_run_id uuid not null references app_private.accounting_sync_runs, provider text not null, provider_customer_id text not null, provider_version text not null, provider_modified_at timestamptz not null, received_at timestamptz not null default now(), normalized_data jsonb not null, source_fingerprint text not null check(source_fingerprint~'^[a-f0-9]{64}$'), archived boolean not null default false, unique(provider,provider_customer_id,provider_version,source_fingerprint));
create table app_private.accounting_invoice_facts(
 accounting_invoice_fact_id uuid primary key default gen_random_uuid(), accounting_sync_run_id uuid not null references app_private.accounting_sync_runs, provider text not null, provider_invoice_id text not null, provider_customer_id text not null, provider_version text not null, provider_modified_at timestamptz not null, received_at timestamptz not null default now(), invoice_number text not null, issue_date date not null, due_date date not null, total_minor bigint not null, outstanding_minor bigint not null, currency char(3) not null, normalized_status text not null check(normalized_status in('draft','open','partially_paid','paid','void','unknown')), source_fingerprint text not null check(source_fingerprint~'^[a-f0-9]{64}$'), unique(provider,provider_invoice_id,provider_version,source_fingerprint));
create index accounting_invoice_customer_due_idx on app_private.accounting_invoice_facts(provider,provider_customer_id,due_date);
create table app_private.accounting_payment_facts(
 accounting_payment_fact_id uuid primary key default gen_random_uuid(), accounting_sync_run_id uuid not null references app_private.accounting_sync_runs, provider text not null, provider_payment_id text not null, provider_customer_id text not null, provider_version text not null, provider_modified_at timestamptz not null, received_at timestamptz not null default now(), payment_date date not null, amount_minor bigint not null, currency char(3) not null, payment_reference text, source_fingerprint text not null check(source_fingerprint~'^[a-f0-9]{64}$'), unique(provider,provider_payment_id,provider_version,source_fingerprint));
create table app_private.accounting_adjustment_facts(
 accounting_adjustment_fact_id uuid primary key default gen_random_uuid(), accounting_sync_run_id uuid not null references app_private.accounting_sync_runs, provider text not null, provider_adjustment_id text not null, provider_customer_id text not null, provider_version text not null, provider_modified_at timestamptz not null, received_at timestamptz not null default now(), amount_minor bigint not null, currency char(3) not null, normalized_status text not null check(normalized_status in('active','void')), source_fingerprint text not null check(source_fingerprint~'^[a-f0-9]{64}$'), unique(provider,provider_adjustment_id,provider_version,source_fingerprint));
create table app_private.accounting_customer_reconciliations(
 accounting_customer_reconciliation_id uuid primary key default gen_random_uuid(), provider text not null, provider_customer_id text not null, classification text not null check(classification in('mapped','strong_candidate','ambiguous','unmatched','conflict','ignored','follow_up')), candidate_client_ids uuid[] not null default '{}', mapped_client_id uuid references app_private.clients, reason text, reviewed_by uuid references auth.users, reviewed_at timestamptz, version integer not null default 0, updated_at timestamptz not null default now(), unique(provider,provider_customer_id));
create table app_private.client_accounting_snapshots(
 client_id uuid primary key references app_private.clients, provider text not null, provider_customer_id text not null, service_region_id uuid references app_private.service_regions, currency char(3) not null, total_outstanding_minor bigint not null, overdue_outstanding_minor bigint not null, oldest_overdue_date date, days_overdue integer not null, unpaid_invoice_count integer not null, overdue_invoice_count integer not null, latest_payment_date date, aging_bucket text not null check(aging_bucket in('current','1_30','31_60','61_90','90_plus')), derived_status text not null check(derived_status in('unknown','current','due_soon','overdue','seriously_overdue','manual_review')), provider_synced_at timestamptz not null, stale_after timestamptz not null, reconciliation_status text not null, source_sync_run_id uuid not null references app_private.accounting_sync_runs, updated_at timestamptz not null default now());
create index client_accounting_snapshots_region_status_idx on app_private.client_accounting_snapshots(service_region_id,derived_status);
create table app_private.accounting_status_exceptions(
 accounting_status_exception_id uuid primary key default gen_random_uuid(), client_id uuid not null references app_private.clients, override_status text not null check(override_status in('current','manual_review','unknown')), reason text not null check(length(btrim(reason))>=3), effective_from timestamptz not null default now(), effective_until timestamptz, created_by uuid not null references auth.users, created_at timestamptz not null default now(), revoked_by uuid references auth.users, revoked_at timestamptz, revoke_reason text, check(effective_until is null or effective_until>effective_from));
create unique index accounting_exception_one_active_idx on app_private.accounting_status_exceptions(client_id) where revoked_at is null;

alter table app_private.accounting_connections enable row level security; alter table app_private.accounting_sync_runs enable row level security; alter table app_private.accounting_customer_facts enable row level security; alter table app_private.accounting_invoice_facts enable row level security; alter table app_private.accounting_payment_facts enable row level security; alter table app_private.accounting_adjustment_facts enable row level security; alter table app_private.accounting_customer_reconciliations enable row level security; alter table app_private.client_accounting_snapshots enable row level security; alter table app_private.accounting_status_exceptions enable row level security;
revoke all on app_private.accounting_connections,app_private.accounting_sync_runs,app_private.accounting_customer_facts,app_private.accounting_invoice_facts,app_private.accounting_payment_facts,app_private.accounting_adjustment_facts,app_private.accounting_customer_reconciliations,app_private.client_accounting_snapshots,app_private.accounting_status_exceptions from public,anon,authenticated;
grant all on app_private.accounting_connections,app_private.accounting_sync_runs,app_private.accounting_customer_facts,app_private.accounting_invoice_facts,app_private.accounting_payment_facts,app_private.accounting_adjustment_facts,app_private.accounting_customer_reconciliations,app_private.client_accounting_snapshots,app_private.accounting_status_exceptions to service_role;

create or replace function app_private.accounting_require(p_actor uuid,p_permission text,p_region uuid default null) returns void language plpgsql security definer set search_path='' as $$begin if p_region is null then if not app_private.user_has_global_permission(p_actor,p_permission) then raise exception 'permission_denied' using errcode='42501';end if;elsif not app_private.user_has_region_permission(p_actor,p_permission,p_region)then raise exception 'region_denied' using errcode='42501';end if;end$$;

create or replace function api.accounting_start_sync(p_actor uuid,p_body jsonb,p_correlation uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.accounting_connections%rowtype;r app_private.accounting_sync_runs%rowtype;begin perform app_private.accounting_require(p_actor,'accounting.sync');select * into c from app_private.accounting_connections where environment_name=p_body->>'environment' order by updated_at desc limit 1;if c.accounting_connection_id is null then insert into app_private.accounting_connections(provider,environment_name,organization_reference,lifecycle_status,credential_reference)values(p_body->>'provider',p_body->>'environment',p_body->>'organizationId','configured',p_body->>'credentialReference')returning * into c;end if;if exists(select 1 from app_private.accounting_sync_runs where accounting_connection_id=c.accounting_connection_id and lifecycle_status in('pending','running'))then raise exception 'sync_running' using errcode='55000';end if;insert into app_private.accounting_sync_runs(accounting_connection_id,provider,environment_name,sync_mode,lifecycle_status,cursor_before,initiated_by,initiation_kind,correlation_id)values(c.accounting_connection_id,c.provider,c.environment_name,p_body->>'syncMode','pending',p_body->>'cursor',p_actor,'user',p_correlation)returning * into r;update app_private.accounting_connections set last_attempt_at=now(),updated_at=now()where accounting_connection_id=c.accounting_connection_id;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('accounting.sync_started',p_actor,'accounting','accounting-sync-run',r.accounting_sync_run_id,p_correlation,jsonb_build_object('provider',r.provider,'mode',r.sync_mode));return jsonb_build_object('syncRunId',r.accounting_sync_run_id,'status',r.lifecycle_status);end$$;

create or replace function api.accounting_ingest_sync(p_sync_run uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare r app_private.accounting_sync_runs%rowtype;x jsonb;client_candidates uuid[];match_classification text;client_match uuid;sync_time timestamptz:=now();begin select * into r from app_private.accounting_sync_runs where accounting_sync_run_id=p_sync_run for update;if r.lifecycle_status not in('pending','running')then return jsonb_build_object('duplicate',true,'status',r.lifecycle_status);end if;update app_private.accounting_sync_runs set lifecycle_status='running',started_at=coalesce(started_at,now())where accounting_sync_run_id=p_sync_run;
for x in select * from jsonb_array_elements(coalesce(p_payload->'customers','[]'))loop insert into app_private.accounting_customer_facts(accounting_sync_run_id,provider,provider_customer_id,provider_version,provider_modified_at,normalized_data,source_fingerprint,archived)values(p_sync_run,r.provider,x->>'externalId',x->>'version',(x->>'modifiedAt')::timestamptz,x,x->>'fingerprint',coalesce((x->>'archived')::boolean,false))on conflict do nothing;select array_agg(distinct c.client_id) into client_candidates from app_private.clients c left join app_private.client_contacts cc on cc.client_id=c.client_id left join app_private.external_references er on er.internal_entity_id=c.client_id and er.entity_type='client' and er.retired_at is null where(er.source_system=r.provider and er.external_identifier=x->>'externalId')or(nullif(lower(x->>'email'),'') is not null and lower(cc.email)=lower(x->>'email'))or(nullif(x->>'mobile','') is not null and cc.mobile_e164=x->>'mobile');client_match:=case when cardinality(client_candidates)=1 then client_candidates[1] end;match_classification:=case when exists(select 1 from app_private.external_references er where er.source_system=r.provider and er.entity_type='client' and er.external_identifier=x->>'externalId')and client_match is not null then'mapped'when cardinality(client_candidates)=1 then'strong_candidate'when cardinality(client_candidates)>1 then'ambiguous'else'unmatched'end;insert into app_private.accounting_customer_reconciliations(provider,provider_customer_id,classification,candidate_client_ids,mapped_client_id)values(r.provider,x->>'externalId',match_classification,coalesce(client_candidates,'{}'),case when match_classification='mapped'then client_match end)on conflict(provider,provider_customer_id)do update set classification=case when app_private.accounting_customer_reconciliations.mapped_client_id is not null then'mapped'else excluded.classification end,candidate_client_ids=excluded.candidate_client_ids,updated_at=now();end loop;
for x in select * from jsonb_array_elements(coalesce(p_payload->'invoices','[]'))loop insert into app_private.accounting_invoice_facts(accounting_sync_run_id,provider,provider_invoice_id,provider_customer_id,provider_version,provider_modified_at,invoice_number,issue_date,due_date,total_minor,outstanding_minor,currency,normalized_status,source_fingerprint)values(p_sync_run,r.provider,x->>'externalId',x->>'customerExternalId',x->>'version',(x->>'modifiedAt')::timestamptz,x->>'invoiceNumber',(x->>'issueDate')::date,(x->>'dueDate')::date,(x->>'totalMinor')::bigint,(x->>'outstandingMinor')::bigint,x->>'currency',x->>'status',x->>'fingerprint')on conflict do nothing;end loop;
for x in select * from jsonb_array_elements(coalesce(p_payload->'payments','[]'))loop insert into app_private.accounting_payment_facts(accounting_sync_run_id,provider,provider_payment_id,provider_customer_id,provider_version,provider_modified_at,payment_date,amount_minor,currency,payment_reference,source_fingerprint)values(p_sync_run,r.provider,x->>'externalId',x->>'customerExternalId',x->>'version',(x->>'modifiedAt')::timestamptz,(x->>'paymentDate')::date,(x->>'amountMinor')::bigint,x->>'currency',x->>'reference',x->>'fingerprint')on conflict do nothing;end loop;
for x in select * from jsonb_array_elements(coalesce(p_payload->'adjustments','[]'))loop insert into app_private.accounting_adjustment_facts(accounting_sync_run_id,provider,provider_adjustment_id,provider_customer_id,provider_version,provider_modified_at,amount_minor,currency,normalized_status,source_fingerprint)values(p_sync_run,r.provider,x->>'externalId',x->>'customerExternalId',x->>'version',(x->>'modifiedAt')::timestamptz,(x->>'amountMinor')::bigint,x->>'currency',x->>'status',x->>'fingerprint')on conflict do nothing;end loop;
with mapped as(select q.provider_customer_id,q.mapped_client_id from app_private.accounting_customer_reconciliations q where q.provider=r.provider and q.classification='mapped'),latest_invoice as(select distinct on(provider_invoice_id)* from app_private.accounting_invoice_facts where provider=r.provider order by provider_invoice_id,provider_modified_at desc,received_at desc),latest_payment as(select distinct on(provider_payment_id)* from app_private.accounting_payment_facts where provider=r.provider order by provider_payment_id,provider_modified_at desc,received_at desc),latest_adjustment as(select distinct on(provider_adjustment_id)* from app_private.accounting_adjustment_facts where provider=r.provider order by provider_adjustment_id,provider_modified_at desc,received_at desc),invoice_totals as(select provider_customer_id,coalesce(max(currency),'ZAR')currency,coalesce(sum(outstanding_minor)filter(where normalized_status not in('paid','void')),0)total,coalesce(sum(outstanding_minor)filter(where due_date<current_date and normalized_status not in('paid','void')),0)overdue,min(due_date)filter(where due_date<current_date and outstanding_minor>0 and normalized_status not in('paid','void'))oldest,count(*)filter(where outstanding_minor>0 and normalized_status not in('paid','void'))unpaid,count(*)filter(where due_date<current_date and outstanding_minor>0 and normalized_status not in('paid','void'))overdue_count,min(due_date)filter(where due_date>=current_date and outstanding_minor>0 and normalized_status not in('paid','void'))next_due from latest_invoice group by provider_customer_id),payment_totals as(select provider_customer_id,max(payment_date)latest_payment from latest_payment group by provider_customer_id),adjustment_totals as(select provider_customer_id,coalesce(sum(amount_minor)filter(where normalized_status='active'),0)adjustment from latest_adjustment group by provider_customer_id),totals as(select m.mapped_client_id client_id,m.provider_customer_id,coalesce(i.currency,'ZAR')currency,greatest(coalesce(i.total,0)+coalesce(a.adjustment,0),0)total,greatest(coalesce(i.overdue,0)+coalesce(a.adjustment,0),0)overdue,i.oldest,coalesce(i.unpaid,0)unpaid,coalesce(i.overdue_count,0)overdue_count,i.next_due,p.latest_payment from mapped m left join invoice_totals i using(provider_customer_id)left join payment_totals p using(provider_customer_id)left join adjustment_totals a using(provider_customer_id)),regions as(select distinct on(cs.client_id)cs.client_id,sc.service_region_id from app_private.client_services cs left join app_private.service_configurations sc on sc.client_service_id=cs.client_service_id and sc.effective_to is null order by cs.client_id,sc.effective_from desc)insert into app_private.client_accounting_snapshots(client_id,provider,provider_customer_id,service_region_id,currency,total_outstanding_minor,overdue_outstanding_minor,oldest_overdue_date,days_overdue,unpaid_invoice_count,overdue_invoice_count,latest_payment_date,aging_bucket,derived_status,provider_synced_at,stale_after,reconciliation_status,source_sync_run_id)select t.client_id,r.provider,t.provider_customer_id,g.service_region_id,t.currency,t.total,t.overdue,t.oldest,coalesce(current_date-t.oldest,0),t.unpaid,t.overdue_count,t.latest_payment,case when t.oldest is null then'current'when current_date-t.oldest<=30 then'1_30'when current_date-t.oldest<=60 then'31_60'when current_date-t.oldest<=90 then'61_90'else'90_plus'end,case when t.oldest is not null and current_date-t.oldest>=((select default_value#>>'{}'from app_private.configuration_definitions where configuration_key='accounting.serious-overdue-days')::integer)then'seriously_overdue'when t.oldest is not null then'overdue'when t.next_due is not null and t.next_due-current_date<=((select default_value#>>'{}'from app_private.configuration_definitions where configuration_key='accounting.due-soon-days')::integer)then'due_soon'else'current'end,sync_time,sync_time+make_interval(hours=>((select default_value#>>'{}'from app_private.configuration_definitions where configuration_key='accounting.stale-after-hours')::integer)),'mapped',p_sync_run from totals t left join regions g on g.client_id=t.client_id on conflict(client_id)do update set total_outstanding_minor=excluded.total_outstanding_minor,overdue_outstanding_minor=excluded.overdue_outstanding_minor,oldest_overdue_date=excluded.oldest_overdue_date,days_overdue=excluded.days_overdue,unpaid_invoice_count=excluded.unpaid_invoice_count,overdue_invoice_count=excluded.overdue_invoice_count,latest_payment_date=excluded.latest_payment_date,aging_bucket=excluded.aging_bucket,derived_status=excluded.derived_status,provider_synced_at=excluded.provider_synced_at,stale_after=excluded.stale_after,source_sync_run_id=excluded.source_sync_run_id,updated_at=now();
update app_private.accounting_sync_runs set lifecycle_status='succeeded',completed_at=now(),cursor_after=p_payload->>'nextCursor',fetched_counts=jsonb_build_object('customers',jsonb_array_length(coalesce(p_payload->'customers','[]')),'invoices',jsonb_array_length(coalesce(p_payload->'invoices','[]')),'payments',jsonb_array_length(coalesce(p_payload->'payments','[]')),'adjustments',jsonb_array_length(coalesce(p_payload->'adjustments','[]'))),processed_counts=jsonb_build_object('snapshots',(select count(*)from app_private.client_accounting_snapshots where source_sync_run_id=p_sync_run)),reconciliation_counts=coalesce((select jsonb_object_agg(classification,n)from(select classification,count(*)n from app_private.accounting_customer_reconciliations where provider=r.provider group by classification)s),'{}'),provider_metadata=coalesce(p_payload->'providerMetadata','{}')where accounting_sync_run_id=p_sync_run;update app_private.accounting_connections set lifecycle_status='active',last_successful_sync_at=now(),health_summary='Healthy',updated_at=now()where accounting_connection_id=r.accounting_connection_id;insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('accounting','Accounting.SyncCompleted',1,'accounting-sync-run',p_sync_run,jsonb_build_object('syncRunId',p_sync_run,'status','succeeded'),r.correlation_id,'system','accounting-sync',now());return jsonb_build_object('syncRunId',p_sync_run,'status','succeeded');end$$;

create or replace function api.accounting_fail_sync(p_sync_run uuid,p_classification text,p_message text,p_retry_after_ms integer default null)returns jsonb language plpgsql security definer set search_path='' as $$declare r app_private.accounting_sync_runs%rowtype;health text;begin select * into r from app_private.accounting_sync_runs where accounting_sync_run_id=p_sync_run for update;health:=case when p_classification='authentication'then'authentication_required'when p_classification in('rate_limited','provider_unavailable','transient_network')then'degraded'else'unhealthy'end;update app_private.accounting_sync_runs set lifecycle_status='failed',completed_at=now(),failure_classification=p_classification,safe_failure_message=p_message,provider_metadata=provider_metadata||jsonb_strip_nulls(jsonb_build_object('retryAfterMs',p_retry_after_ms))where accounting_sync_run_id=p_sync_run;update app_private.accounting_connections set lifecycle_status=health,last_attempt_at=now(),health_summary=p_message,updated_at=now()where accounting_connection_id=r.accounting_connection_id;return jsonb_build_object('syncRunId',p_sync_run,'status','failed','classification',p_classification);end$$;

create or replace function api.accounting_reconcile(p_actor uuid,p_provider text,p_customer text,p_action text,p_client uuid,p_reason text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare q app_private.accounting_customer_reconciliations%rowtype;region uuid;begin select distinct sc.service_region_id into region from app_private.client_services cs join app_private.service_configurations sc using(client_service_id)where cs.client_id=p_client and sc.effective_to is null limit 1;perform app_private.accounting_require(p_actor,'accounting.reconcile',region);if p_action='link'and p_client is null then raise exception 'client_required' using errcode='22023';end if;if p_action not in('link','ignore','follow_up','resolve_conflict')then raise exception 'invalid_action' using errcode='22023';end if;update app_private.accounting_customer_reconciliations set classification=case p_action when'link'then'mapped'when'ignore'then'ignored'when'follow_up'then'follow_up'else'unmatched'end,mapped_client_id=case when p_action='link'then p_client else null end,reason=p_reason,reviewed_by=p_actor,reviewed_at=now(),version=version+1,updated_at=now()where provider=p_provider and provider_customer_id=p_customer returning * into q;if q.accounting_customer_reconciliation_id is null then raise exception 'not_found' using errcode='P0002';end if;if p_action='link'then insert into app_private.external_references(source_system,entity_type,internal_entity_id,external_identifier)values(p_provider,'client',p_client,p_customer)on conflict do nothing;end if;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('accounting.customer_'||p_action,p_actor,'accounting','accounting-reconciliation',q.accounting_customer_reconciliation_id,p_correlation,jsonb_build_object('classification',q.classification,'clientId',q.mapped_client_id,'reason',p_reason));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('accounting','Accounting.CustomerMapped',1,'accounting-customer',q.accounting_customer_reconciliation_id,jsonb_build_object('provider',p_provider,'customerReference',p_customer,'clientId',p_client),p_correlation,'user',p_actor::text,now());return to_jsonb(q);end$$;

create or replace function api.accounting_set_exception(p_actor uuid,p_client uuid,p_status text,p_reason text,p_until timestamptz,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e app_private.accounting_status_exceptions%rowtype;region uuid;begin select service_region_id into region from app_private.client_accounting_snapshots where client_id=p_client;perform app_private.accounting_require(p_actor,'accounting.exception.manage',region);if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;update app_private.accounting_status_exceptions set revoked_by=p_actor,revoked_at=now(),revoke_reason='superseded'where client_id=p_client and revoked_at is null;insert into app_private.accounting_status_exceptions(client_id,override_status,reason,effective_until,created_by)values(p_client,p_status,p_reason,p_until,p_actor)returning * into e;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('accounting.exception_changed',p_actor,'accounting','client',p_client,p_correlation,jsonb_build_object('status',p_status,'reason',p_reason,'effectiveUntil',p_until));insert into app_private.outbox_events(producer_module,event_name,event_version,aggregate_type,aggregate_id,payload,correlation_id,actor_kind,actor_id,occurred_at)values('accounting','Accounting.ExceptionChanged',1,'client',p_client,jsonb_build_object('clientId',p_client,'status',p_status),p_correlation,'user',p_actor::text,now());return to_jsonb(e);end$$;
create or replace function api.accounting_remove_exception(p_actor uuid,p_client uuid,p_reason text,p_correlation uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare region uuid;begin select service_region_id into region from app_private.client_accounting_snapshots where client_id=p_client;perform app_private.accounting_require(p_actor,'accounting.exception.manage',region);if length(btrim(coalesce(p_reason,'')))<3 then raise exception 'reason_required' using errcode='22023';end if;update app_private.accounting_status_exceptions set revoked_by=p_actor,revoked_at=now(),revoke_reason=p_reason where client_id=p_client and revoked_at is null;insert into app_private.business_audit_facts(action_key,actor_id,module_key,target_type,target_id,correlation_id,after_state)values('accounting.exception_removed',p_actor,'accounting','client',p_client,p_correlation,jsonb_build_object('reason',p_reason));return jsonb_build_object('clientId',p_client,'removed',true);end$$;

create or replace function api.accounting_status_list(p_actor uuid,p_query jsonb default '{}')returns jsonb language plpgsql security definer set search_path='' as $$begin return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('clientId',s.client_id,'clientName',c.display_name,'serviceRegionId',s.service_region_id,'accountStatus',coalesce(e.override_status,case when now()>s.stale_after then'unknown'else s.derived_status end),'derivedStatus',s.derived_status,'isStale',now()>s.stale_after,'reconciliationStatus',s.reconciliation_status,'lastSync',s.provider_synced_at,'exception',case when e.accounting_status_exception_id is null then null else jsonb_build_object('status',e.override_status,'reason',e.reason,'effectiveUntil',e.effective_until)end)order by c.display_name),'[]')from app_private.client_accounting_snapshots s join app_private.clients c using(client_id)left join app_private.accounting_status_exceptions e on e.client_id=s.client_id and e.revoked_at is null and(e.effective_until is null or e.effective_until>now())where app_private.user_has_region_permission(p_actor,'accounting.read',s.service_region_id)and(nullif(p_query->>'status','')is null or coalesce(e.override_status,case when now()>s.stale_after then'unknown'else s.derived_status end)=p_query->>'status')));end$$;
create or replace function api.accounting_client_detail(p_actor uuid,p_client uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare s app_private.client_accounting_snapshots%rowtype;e app_private.accounting_status_exceptions%rowtype;sensitive boolean;begin select * into s from app_private.client_accounting_snapshots where client_id=p_client;if s.client_id is null then raise exception 'not_found' using errcode='P0002';end if;perform app_private.accounting_require(p_actor,'accounting.read',s.service_region_id);sensitive:=app_private.user_has_region_permission(p_actor,'accounting.sensitive.read',s.service_region_id);select * into e from app_private.accounting_status_exceptions where client_id=p_client and revoked_at is null and(effective_until is null or effective_until>now());return jsonb_build_object('clientId',p_client,'provider',s.provider,'providerCustomerId',s.provider_customer_id,'accountStatus',coalesce(e.override_status,case when now()>s.stale_after then'unknown'else s.derived_status end),'derivedStatus',s.derived_status,'isStale',now()>s.stale_after,'freshness',case when now()>s.stale_after then'stale'else'current'end,'reconciliationStatus',s.reconciliation_status,'lastSync',s.provider_synced_at,'exception',to_jsonb(e),'eligibility',jsonb_build_object('accountStatus',coalesce(e.override_status,case when now()>s.stale_after then'unknown'else s.derived_status end),'statusFreshness',case when now()>s.stale_after then'stale'else'current'end,'manualException',e.accounting_status_exception_id is not null,'providerReconciliationState',s.reconciliation_status,'recommendation',case when now()>s.stale_after or e.override_status='manual_review'then'review_required'when coalesce(e.override_status,s.derived_status) in('overdue','seriously_overdue')then'financial_attention'else'no_financial_block_recommended'end), 'financial',case when sensitive then jsonb_build_object('currency',s.currency,'totalOutstandingMinor',s.total_outstanding_minor,'overdueOutstandingMinor',s.overdue_outstanding_minor,'oldestOverdueDate',s.oldest_overdue_date,'daysOverdue',s.days_overdue,'unpaidInvoiceCount',s.unpaid_invoice_count,'overdueInvoiceCount',s.overdue_invoice_count,'latestPaymentDate',s.latest_payment_date,'agingBucket',s.aging_bucket,'invoices',(select coalesce(jsonb_agg(to_jsonb(i)order by due_date desc),'[]')from app_private.accounting_invoice_facts i where i.provider=s.provider and i.provider_customer_id=s.provider_customer_id),'payments',(select coalesce(jsonb_agg(to_jsonb(p)order by payment_date desc),'[]')from app_private.accounting_payment_facts p where p.provider=s.provider and p.provider_customer_id=s.provider_customer_id))else null end);end$$;
create or replace function api.accounting_reconciliation_queue(p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.accounting_require(p_actor,'accounting.reconcile');return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('provider',q.provider,'providerCustomerId',q.provider_customer_id,'classification',q.classification,'candidateClientIds',q.candidate_client_ids,'mappedClientId',q.mapped_client_id,'version',q.version,'customer',f.normalized_data)order by q.updated_at desc),'[]')from app_private.accounting_customer_reconciliations q left join lateral(select normalized_data from app_private.accounting_customer_facts where provider=q.provider and provider_customer_id=q.provider_customer_id order by provider_modified_at desc limit 1)f on true where q.classification not in('mapped','ignored')));end$$;
create or replace function api.accounting_sync_runs(p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.accounting_require(p_actor,'accounting.sync');return jsonb_build_object('items',(select coalesce(jsonb_agg(jsonb_build_object('syncRunId',accounting_sync_run_id,'provider',provider,'syncMode',sync_mode,'status',lifecycle_status,'startedAt',started_at,'completedAt',completed_at,'fetchedCounts',fetched_counts,'failureClassification',failure_classification)order by created_at desc),'[]')from app_private.accounting_sync_runs));end$$;
create or replace function api.accounting_health(p_actor uuid)returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.accounting_require(p_actor,'accounting.read');return coalesce((select jsonb_build_object('provider',provider,'status',lifecycle_status,'lastSuccessfulSync',last_successful_sync_at,'lastAttempt',last_attempt_at,'summary',health_summary)from app_private.accounting_connections order by updated_at desc limit 1),jsonb_build_object('status','unknown'));end$$;

revoke all on function app_private.accounting_require(uuid,text,uuid)from public,anon,authenticated;
revoke all on function api.accounting_start_sync(uuid,jsonb,uuid),api.accounting_ingest_sync(uuid,jsonb),api.accounting_fail_sync(uuid,text,text,integer),api.accounting_reconcile(uuid,text,text,text,uuid,text,uuid),api.accounting_set_exception(uuid,uuid,text,text,timestamptz,uuid),api.accounting_remove_exception(uuid,uuid,text,uuid),api.accounting_status_list(uuid,jsonb),api.accounting_client_detail(uuid,uuid),api.accounting_reconciliation_queue(uuid),api.accounting_sync_runs(uuid),api.accounting_health(uuid)from public,anon,authenticated;
grant execute on function api.accounting_start_sync(uuid,jsonb,uuid),api.accounting_reconcile(uuid,text,text,text,uuid,text,uuid),api.accounting_set_exception(uuid,uuid,text,text,timestamptz,uuid),api.accounting_remove_exception(uuid,uuid,text,uuid),api.accounting_status_list(uuid,jsonb),api.accounting_client_detail(uuid,uuid),api.accounting_reconciliation_queue(uuid),api.accounting_sync_runs(uuid),api.accounting_health(uuid)to service_role;
grant execute on function api.accounting_ingest_sync(uuid,jsonb),api.accounting_fail_sync(uuid,text,text,integer)to service_role;
